```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { axe, toHaveNoViolations } from 'jest-axe';

expect.extend(toHaveNoViolations);

// Mock context providers - gotta set up the course first
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();
const mockItems = [
  { id: '1', name: 'Kourier Board', price: 299.99 },
  { id: '2', name: 'Harpoon Kit', price: 49.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 349.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - Happy Path', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-420-RADICAL' });
  });

  it('completes full checkout flow from shipping to confirmation', async () => {
    // Arrange
    const user = userEvent.setup();
    const onComplete = vi.fn();
    render(<Checkout onComplete={onComplete} />);

    // Act - Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Metaverse Lane');
    await user.type(screen.getByLabelText(/city/i), 'LA');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Act - Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Y.T. Kourier');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Act - Review and place order
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Assert
    await waitFor(() => {
      expect(screen.getByRole('status')).toHaveTextContent('Order Confirmed');
      expect(screen.getByText('ORD-420-RADICAL')).toBeInTheDocument();
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-420-RADICAL');
    expect(mockClearCart).toHaveBeenCalled();
  });
});

describe('Checkout - Validation', () => {
  it('shows inline errors for empty shipping fields', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByText(/city is required/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('rejects invalid ZIP code format', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.type(screen.getByLabelText(/zip/i), 'NOPE');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });

  it('validates card number is 16 digits', async () => {
    const user = userEvent.setup();
    render(<Checkout />);
    // Navigate to payment...
    // Skip shipping for brevity - assume helper fills valid data

    await user.type(screen.getByLabelText(/card number/i), '123');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    expect(screen.getByText(/valid 16-digit card/i)).toBeInTheDocument();
  });
});

describe('Checkout - Error States', () => {
  it('displays payment failure and allows retry', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    const user = userEvent.setup();
    render(<Checkout />);
    // ... navigate to review step

    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent('Card declined');
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});

describe('Checkout - Loading States', () => {
  it('disables buttons and shows processing during submission', async () => {
    mockProcessPayment.mockImplementation(() => new Promise(() => {})); // Never resolves
    const user = userEvent.setup();
    render(<Checkout />);
    // ... navigate to review

    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
    render(<Checkout onCancel={vi.fn()} />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
  });
});

describe('Checkout - Accessibility', () => {
  it('has no accessibility violations on shipping step', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });

  it('marks current step in progress indicator', () => {
    render(<Checkout />);
    expect(screen.getByText('Shipping').closest('li')).toHaveAttribute('aria-current', 'step');
  });
});
```

